-- Existing pending approvals predate attempt fencing and must be renewed.
ALTER TABLE rer_dependency_pending ADD COLUMN attempt_id TEXT;
DELETE FROM rer_dependency_pending;

-- Edition-owned encrypted product state. No item type, title, field, seed,
-- filename, password, device secret or private decryption key is stored here.
CREATE TABLE lky_accounts (
 id TEXT PRIMARY KEY, operator_id TEXT NOT NULL UNIQUE REFERENCES oa_operators(id),
 tenant TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 1,
 opaque_setup TEXT NOT NULL, opaque_record TEXT NOT NULL,
 recipient_key TEXT NOT NULL, recovery_key TEXT NOT NULL, recovery_wrap TEXT NOT NULL, mutation TEXT NOT NULL
);
CREATE TABLE lky_devices (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 public_key TEXT NOT NULL, bundle TEXT NOT NULL, generation INTEGER NOT NULL, revoked_at INTEGER
);
CREATE TABLE lky_exchanges (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL, device_id TEXT NOT NULL,
 state TEXT NOT NULL, generation INTEGER NOT NULL, operator_version INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, used_at INTEGER
);
CREATE TABLE lky_grants (
 token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 device_id TEXT NOT NULL, session_id TEXT NOT NULL, generation INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, recovery INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE lky_nonces (grant_hash TEXT NOT NULL, nonce TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(grant_hash,nonce));
CREATE TABLE lky_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE lky_registrations (
 id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, session_id TEXT NOT NULL,
 tenant TEXT NOT NULL, setup TEXT NOT NULL, expires_at INTEGER NOT NULL
);
CREATE TABLE lky_vaults (
 id TEXT PRIMARY KEY, tenant TEXT NOT NULL, owner TEXT NOT NULL REFERENCES lky_accounts(id),
 epoch INTEGER NOT NULL, revision INTEGER NOT NULL, mutation TEXT NOT NULL
);
CREATE TABLE lky_recipients (
 vault_id TEXT NOT NULL REFERENCES lky_vaults(id), account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 rights TEXT NOT NULL, wrapped_key TEXT NOT NULL, PRIMARY KEY(vault_id,account_id)
);
CREATE TABLE lky_versions (
 vault_id TEXT NOT NULL REFERENCES lky_vaults(id), object_id TEXT NOT NULL,
 version INTEGER NOT NULL, envelope TEXT NOT NULL,
 PRIMARY KEY(vault_id,object_id,version)
);
CREATE TABLE lky_enrollments (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 public_key TEXT NOT NULL, transfer_key TEXT NOT NULL, generation INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, approved_wrap TEXT, consumed_at INTEGER, approved_nonce TEXT
);
CREATE TABLE lky_events (
 id TEXT PRIMARY KEY, actor TEXT NOT NULL, device TEXT NOT NULL,
 action TEXT NOT NULL, object_id TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE lky_installation (singleton INTEGER PRIMARY KEY CHECK(singleton=1), id TEXT NOT NULL);

CREATE TABLE lky_password_changes (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 device_id TEXT NOT NULL, generation INTEGER NOT NULL, setup TEXT NOT NULL, expires_at INTEGER NOT NULL
);
CREATE TABLE lky_machines (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 device_id TEXT NOT NULL, generation INTEGER NOT NULL, operator_version INTEGER NOT NULL,
 vault_id TEXT NOT NULL REFERENCES lky_vaults(id), object_id TEXT NOT NULL, epoch INTEGER NOT NULL,
 public_key TEXT NOT NULL, recipient_key TEXT NOT NULL, wrapped_key TEXT NOT NULL,
 expires_at INTEGER NOT NULL, revoked_at INTEGER, mutation TEXT NOT NULL
);

-- The encrypted root holds the corresponding private signing key. A separate
-- public anchor authenticates key distribution, including a malicious store.
ALTER TABLE lky_accounts ADD COLUMN authority_key TEXT NOT NULL DEFAULT '';

-- Only encrypted values and delivery verifiers. URL fragments and passwords
-- never cross the client boundary. Grants are snapshots, not future key grants.
CREATE TABLE lky_sharing_policy (
 tenant TEXT PRIMARY KEY, external_enabled INTEGER NOT NULL DEFAULT 0,
 domains TEXT NOT NULL DEFAULT '[]', default_days INTEGER NOT NULL DEFAULT 7,
 max_days INTEGER NOT NULL DEFAULT 30, mutation TEXT NOT NULL
);
CREATE TABLE lky_share_groups (id TEXT PRIMARY KEY,tenant TEXT NOT NULL,created_by TEXT NOT NULL);
CREATE TABLE lky_share_group_members (
 group_id TEXT NOT NULL REFERENCES lky_share_groups(id),account_id TEXT NOT NULL REFERENCES lky_accounts(id),
 PRIMARY KEY(group_id,account_id)
);
CREATE TABLE lky_shares (
 id TEXT PRIMARY KEY,tenant TEXT NOT NULL,vault_id TEXT NOT NULL REFERENCES lky_vaults(id),
 source_account TEXT NOT NULL,source_device TEXT NOT NULL,source_generation INTEGER NOT NULL,
 source_operator_version INTEGER NOT NULL,epoch INTEGER NOT NULL,scope TEXT NOT NULL,
 group_id TEXT,rights TEXT NOT NULL,starts_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,
 approved_at INTEGER,revoked_at INTEGER,created_at INTEGER NOT NULL,mutation TEXT NOT NULL
);
CREATE TABLE lky_share_keys (
 share_id TEXT NOT NULL REFERENCES lky_shares(id),account_id TEXT NOT NULL,
 recipient_generation INTEGER NOT NULL,object_id TEXT NOT NULL,version INTEGER NOT NULL,
 wrapped_key TEXT NOT NULL,PRIMARY KEY(share_id,account_id,object_id)
);
CREATE TABLE lky_links (
 id TEXT PRIMARY KEY,tenant TEXT NOT NULL,vault_id TEXT NOT NULL REFERENCES lky_vaults(id),
 object_id TEXT NOT NULL,source_version INTEGER NOT NULL,epoch INTEGER NOT NULL,
 source_account TEXT NOT NULL,source_device TEXT NOT NULL,source_generation INTEGER NOT NULL,
 source_operator_version INTEGER NOT NULL,verifier_hash TEXT NOT NULL,
 password_salt TEXT NOT NULL,password_required INTEGER NOT NULL,recipient_email TEXT NOT NULL,
 envelope TEXT NOT NULL,starts_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,
 max_views INTEGER NOT NULL,views INTEGER NOT NULL DEFAULT 0,revoked_at INTEGER,
 created_at INTEGER NOT NULL,mutation TEXT NOT NULL
);
CREATE TABLE lky_link_challenges (
 id TEXT PRIMARY KEY,link_id TEXT NOT NULL REFERENCES lky_links(id),code_hash TEXT NOT NULL,
 expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed_at INTEGER
);
CREATE INDEX lky_share_source ON lky_shares(vault_id,created_at);
CREATE INDEX lky_link_source ON lky_links(vault_id,object_id,created_at);

-- Durable, value-free object fences travel with Records. No credential,
-- attachment, key wrap, recipient email or encrypted value belongs here.
CREATE TABLE lky_erased_items (
 vault_id TEXT NOT NULL REFERENCES lky_vaults(id), object_id TEXT NOT NULL,
 tenant TEXT NOT NULL, receipt_id TEXT NOT NULL UNIQUE,
 erased_by TEXT NOT NULL, erased_device TEXT NOT NULL, erased_at INTEGER NOT NULL,
 revision INTEGER NOT NULL, counts TEXT NOT NULL,
 PRIMARY KEY(vault_id,object_id)
);
-- This empty CHECK table makes authority/inventory failures roll back the
-- entire D1 batch, including unconditional Base journal statements.
CREATE TABLE lky_erasure_guard (value INTEGER NOT NULL CHECK(value=1));
CREATE INDEX lky_machine_object ON lky_machines(vault_id,object_id);
CREATE INDEX lky_share_key_object ON lky_share_keys(object_id,share_id);

-- Generator policy contains constraints only. Generated values and history
-- remain encrypted in each client and never enter these tables.
CREATE TABLE lky_generator_policies (
 tenant TEXT NOT NULL, scope TEXT NOT NULL, group_id TEXT REFERENCES lky_share_groups(id),
 policy TEXT NOT NULL, mutation TEXT NOT NULL,
 PRIMARY KEY(tenant,scope),
 CHECK((scope='company' AND group_id IS NULL) OR (group_id IS NOT NULL AND scope=group_id))
);
CREATE TABLE lky_generator_policy_changes (
 id TEXT PRIMARY KEY,tenant TEXT NOT NULL,group_id TEXT,actor TEXT NOT NULL,device TEXT NOT NULL,
 reason TEXT NOT NULL,policy TEXT NOT NULL,created_at INTEGER NOT NULL
);

-- Original person identifiers are never retained in these receipts/fences.
-- HMAC custody is the separately held LATCHKEY_ERASURE_SECRET configuration.
CREATE TABLE lky_subject_erasures (
 id TEXT PRIMARY KEY,tenant TEXT NOT NULL,label TEXT NOT NULL,
 phase TEXT NOT NULL CHECK(phase='control-plane-erased'),counts TEXT NOT NULL,
 outstanding TEXT NOT NULL,created_at INTEGER NOT NULL,proof TEXT NOT NULL
);
CREATE TABLE lky_subject_fences (
 tenant TEXT NOT NULL,kind TEXT NOT NULL,digest TEXT NOT NULL,
 operation TEXT NOT NULL REFERENCES lky_subject_erasures(id),created_at INTEGER NOT NULL,
 PRIMARY KEY(tenant,kind,digest)
);
CREATE TABLE lky_subject_invalidations (
 tenant TEXT NOT NULL,vault_id TEXT NOT NULL REFERENCES lky_vaults(id),
 operation TEXT NOT NULL REFERENCES lky_subject_erasures(id),epoch INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('pending','rotated')),
 PRIMARY KEY(vault_id,operation)
);
CREATE TABLE lky_subject_audit (
 operation TEXT NOT NULL REFERENCES lky_subject_erasures(id),position INTEGER NOT NULL,
 facts TEXT NOT NULL,previous_hash TEXT NOT NULL,hash TEXT NOT NULL,
 PRIMARY KEY(operation,position)
);
CREATE TABLE lky_subject_guard(value INTEGER NOT NULL CHECK(value=1));

-- Connected clients accept history removal only with the vault owner's
-- independently pinned authority signature. The proof contains no item value.
ALTER TABLE lky_erased_items ADD COLUMN proof TEXT NOT NULL DEFAULT '{}';

-- Access metadata only. Item values, wraps, link capabilities and provider keys
-- never enter review snapshots or signed evidence.
CREATE TABLE lky_reviews (
 id TEXT PRIMARY KEY,tenant TEXT NOT NULL,vault_id TEXT NOT NULL,owner TEXT NOT NULL,
 reviewer TEXT NOT NULL,period TEXT NOT NULL,phase TEXT NOT NULL,
 scheduled_at INTEGER NOT NULL,due_at INTEGER NOT NULL,created_at INTEGER NOT NULL,
 as_of INTEGER,policy_version TEXT NOT NULL,snapshot TEXT NOT NULL,
 closed_at INTEGER,package TEXT
);
CREATE TABLE lky_review_rows (
 review_id TEXT NOT NULL,key TEXT NOT NULL,snapshot TEXT NOT NULL,
 reviewer TEXT NOT NULL,decision TEXT,reason TEXT,decided_at INTEGER,
 superseded INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(review_id,key)
);
CREATE TABLE lky_review_reminders (
 review_id TEXT NOT NULL,reviewer TEXT NOT NULL,day INTEGER NOT NULL,
 created_at INTEGER NOT NULL,PRIMARY KEY(review_id,reviewer,day)
);
CREATE TABLE lky_review_guard (value INTEGER NOT NULL CHECK(value=1));

ALTER TABLE lky_vaults ADD COLUMN kind TEXT NOT NULL DEFAULT 'company';
ALTER TABLE lky_vaults ADD COLUMN trash_policy TEXT;
-- Restore and delete are independently delegated; inactive imported recipients
-- stay inactive. Existing active owners receive the new owner capabilities.
UPDATE lky_recipients SET rights=json_insert(json_insert(rights,'$[#]','delete'),'$[#]','restore')
 WHERE account_id=(SELECT owner FROM lky_vaults WHERE id=vault_id) AND json_array_length(rights)>0;
CREATE TABLE lky_vault_capabilities (
 vault_id TEXT NOT NULL,account_id TEXT NOT NULL,capability TEXT NOT NULL,
 PRIMARY KEY(vault_id,account_id)
